// Password re-login (account recovery) tests, run offline against the fake
// host caller. The differential fixtures below were generated by RUNNING THE
// REFERENCE IMPLEMENTATION ITSELF (chatgpt2api-ref/utils/sentinel.py and
// utils/pkce.py under Python 3.13.7, generator script dated 2026-11-09), not
// by a parallel Go implementation of the same algorithm — that would only
// prove self-consistency. The frozen seams (fixed wall clock, constant
// random draws, fixed sid) make the reference output reproducible byte for
// byte; the Go port must hit the same bytes.

const (
	testPasswordEmail  = "recovery@example.com"
	testPasswordSecret = "hunter2-synth-SECRET-000"
	testChallengeToken = "challenge-token-XYZ"
	matrixDeviceID     = "device-1234"
)

// matrixFrozenWallTime is the frozen clock the differential vectors were
// generated against (2025-12-08 13:20:00 UTC).
var matrixFrozenWallTime = time.Unix(1765200000, 0)

// fixedSentinelConfig is the frozen 18-element challenge array (reference
// _get_config output with every random/time draw pinned). The SOLVE vectors
// were generated against exactly this array.
var fixedSentinelConfig = []any{
	"1920x1080",
	"Fri Dec 05 2025 12:00:00 GMT+0000 (Coordinated Universal Time)",
	4294705152,
	0.25,
	"UA-FIXED",
	"https://sentinel.openai.com/sentinel/20260124ceb8/sdk.js",
	nil,
	nil,
	"en-US",
	0.5,
	"vendorSub-undefined",
	"location",
	"Object",
	42.5,
	"sid-fixed",
	"",
	8,
	1765200000000,
}

// fixedSentinelSeams pins every random/time draw the differential vectors
// were generated with: float draws 0.25, uniform draws 42.3, choices the
// first option, the wall clock frozen at 2025-12-08 13:20:00 UTC.
func fixedSentinelSeams() sentinelSeams {
	return sentinelSeams{
		float01:   func() float64 { return 0.25 },
		uniform:   func(a, b float64) float64 { return 42.3 },
		choiceStr: func(opts []string) string { return opts[0] },
		choiceInt: func(opts []int) int { return opts[0] },
		wall:      func() time.Time { return matrixFrozenWallTime },
	}
}

// frozenConfigGenerator builds a sentinelGenerator whose config builder
// returns the fixed array (fresh copy per call, as the reference does).
func frozenConfigGenerator() *sentinelGenerator {
	return &sentinelGenerator{
		deviceID:  matrixDeviceID,
		userAgent: "UA-FIXED",
		sidValue:  "sid-fixed",
		seams:     fixedSentinelSeams(),
		config: func() []any {
			return append([]any(nil), fixedSentinelConfig...)
		},
		maxAttempts: sentinelPoWCap,
	}
}

// TestSentinelFnvDifferential pins the FNV-1a-32 (+ sentinel finalizer) port
// against vectors computed by the reference _fnv1a_32 (sentinel.py:28-39).
// The unicode and control-rune rows prove codepoint iteration (Python ord),
// not byte iteration.
func TestSentinelFnvDifferential(t *testing.T) {
	cases := []struct{ text, want string }{
		{"", "ab3e7c0b"},
		{"a", "1a80b1b3"},
		{"abc", "1cc93dbc"},
		{"The quick brown fox jumps over the lazy dog", "cc6bf03d"},
		{"hello world 0123456789", "f63907af"},
		{"üñîçødé — 日本語 🚀", "265c1f0f"},  // non-ASCII: ord(ch) > 255
		{"ctl \x01\x7f end", "71386c56"}, // control runes
		{strings.Repeat("A", 1000), "184e2312"},
	}
	for _, tc := range cases {
		if got := fnv1a32Sentinel(tc.text); got != tc.want {
			t.Errorf("fnv1a32Sentinel(%q) = %q, want reference %q", tc.text, got, tc.want)
		}
	}
}

// TestSentinelPoWDifferential pins the full generate_token loop (config
// mutation at indices 3/9, the payload b64, the hash prefix comparison)
// against tokens the reference generate_token (sentinel.py:74-84) emitted
// for the fixed config + seeds below. An exact token match implies the exact
// solve iteration (it is embedded in the payload at index 3).
func TestSentinelPoWDifferential(t *testing.T) {
	cases := []struct {
		seed       string
		difficulty string
		want       string
	}{
		{
			seed:       "0123456789abcdef",
			difficulty: "0",
			want:       "~S",
		},
		{
			seed:       "0123456789abcdef",
			difficulty: "00",
			want:       "~S",
		},
		{
			seed:       "seed-with-dashes-and-dots-0123",
			difficulty: "0",
			want:       "~S",
		},
	}
	for _, tc := range cases {
		got, err := frozenConfigGenerator().generateToken(tc.seed, tc.difficulty)
		if err != nil {
			t.Fatalf("generateToken(%q, %q): %v", tc.seed, tc.difficulty, err)
		}
		if got != tc.want {
			t.Errorf("generateToken(%q, %q) =\n%s\nwant reference\n%s", tc.seed, tc.difficulty, got, tc.want)
		}
	}
}

// TestSentinelPoWCapBreach pins the iteration cap: an unsatisfiable
// difficulty must return the typed cap error after exactly maxAttempts
// solves — never hang, never emit the reference's silent error-marker token.
func TestSentinelPoWCapBreach(t *testing.T) {
	g := frozenConfigGenerator()
	g.maxAttempts = 5
	// "-" sorts below every hex digit, so no digest can ever satisfy it —
	// the loop must run out the budget and answer the typed cap error.
	token, err := g.generateToken("0123456789abcdef", "-")
	if err != errSentinelPoWCap {
		t.Fatalf("generateToken err = %v, want errSentinelPoWCap", err)
	}
	if token != "" {
		t.Errorf("cap breach still emitted token %q", token)
	}
}

// TestAcquireAuthSentinelDifferential pins the WHOLE sentinel acquisition
// (req body in the reference's json.dumps spacing, the PoW-solved p value,
// the sentinel value envelope, the oai-sc cookie) against the bytes the
// reference build_sentinel_token (sentinel.py:96-159) emitted under the
// frozen seams with scripted response {"token":"challenge-token-XYZ",
// "proofofwork":{"required":true,"seed":"0123456789abcdef","difficulty":"0"}}.
func TestAcquireAuthSentinelDifferential(t *testing.T) {
	g := &sentinelGenerator{
		deviceID:    matrixDeviceID,
		userAgent:   "UA-FIXED",
		sidValue:    "12345678-90ab-cdef-1234-567890abcdef",
		seams:       fixedSentinelSeams(),
		maxAttempts: sentinelPoWCap,
	}
	g.config = g.getRequirementConfig // production builder: the reference's real _get_config under frozen seams

	fake := &httpFakeCaller{httpResults: []hostHTTPResponse{{
		StatusCode: 200,
		Body: mustJSON(t, map[string]any{
			"token":       testChallengeToken,
			"proofofwork": map[string]any{"required": true, "seed": "0123456789abcdef", "difficulty": "0"},
		}),
	}}}
	m := newAuthTestManager(t, fake)
	acq := m.acquireAuthSentinel("cb-1", matrixDeviceID, g)
	if acq.err != nil {
		t.Fatalf("acquireAuthSentinel err = %v", acq.err)
	}
	const wantReqBody = `{"p": "", "id": "device-1234", "flow": "password_verify"}`
	const wantSentinelValue = `{"p":"~S","t":"","c":"challenge-token-XYZ","id":"device-1234","flow":"password_verify"}`

	if acq.token != wantSentinelValue {
		t.Errorf("sentinel value =\n%s\nwant reference\n%s", acq.token, wantSentinelValue)
	}
	if acq.oaiSC != "0"+testChallengeToken {
		t.Errorf("oai-sc = %q, want %q", acq.oaiSC, "0"+testChallengeToken)
	}

	var req hostHTTPRequest
	if err := json.Unmarshal(fake.callFor(t, pluginabi.MethodHostHTTPDo).request, &req); err != nil {
		t.Fatalf("decode captured sentinel req: %v", err)
	}
	if req.URL != sentinelReqURL || req.Method != "POST" {
		t.Errorf("sentinel req = %s %s, want POST %s", req.Method, req.URL, sentinelReqURL)
	}
	if got := string(req.Body); got != wantReqBody {
		t.Errorf("sentinel req body =\n%s\nwant reference\n%s", got, wantReqBody)
	}
	if ct := strings.Join(req.Headers["Content-Type"], ","); ct != "text/plain;charset=UTF-8" {
		t.Errorf("Content-Type = %q", ct)
	}
	if ref := strings.Join(req.Headers["Referer"], ","); ref != sentinelFrameReferer {
		t.Errorf("Referer = %q", ref)
	}
	if org := strings.Join(req.Headers["Origin"], ","); org != sentinelOrigin {
		t.Errorf("Origin = %q", org)
	}
}

// TestAcquireAuthSentinelFallbacks pins the three degraded acquisition paths:
// a non-JSON response falls back to a requirements token with an empty
// challenge (sentinel.py:140-145); a transport failure or a refused/empty
// challenge leaves NO header value at all (account_service.py:694-701 swallows
// the reference's RuntimeError); required:false answers a requirements token
// plus the server challenge.
func TestAcquireAuthSentinelFallbacks(t *testing.T) {
	t.Run("non-JSON response falls back", func(t *testing.T) {
		fake := &httpFakeCaller{httpResults: []hostHTTPResponse{{
			StatusCode: 200,
			Body:       []byte("not json at all"),
		}}}
		m := newAuthTestManager(t, fake)
		acq := m.acquireAuthSentinel("cb-1", matrixDeviceID, newSentinelGenerator(matrixDeviceID, "UA-FIXED", "sid-x"))
		if acq.err != nil || acq.oaiSC != "" {
			t.Fatalf("fallback = %+v, want no error and empty oai-sc", acq)
		}
		var value sentinelValue
		if err := json.Unmarshal([]byte(acq.token), &value); err != nil {
			t.Fatalf("fallback value is not JSON: %v", err)
		}
		if !strings.HasPrefix(value.P, "gAAAAAC") || value.C != "" || value.ID != matrixDeviceID || value.Flow != sentinelFlowPasswordVerify {
			t.Errorf("fallback value = %+v, want requirements p + empty c", value)
		}
	})

	t.Run("transport failure leaves no header", func(t *testing.T) {
		fake := &httpFakeCaller{errorCode: "conn_down"}
		m := newAuthTestManager(t, fake)
		acq := m.acquireAuthSentinel("cb-1", matrixDeviceID, newSentinelGenerator(matrixDeviceID, "UA-FIXED", "sid-x"))
		if acq.err != nil || acq.token != "" || acq.oaiSC != "" {
			t.Fatalf("transport-down acquisition = %+v, want empty (reference swallows)", acq)
		}
	})

	t.Run("refused challenge leaves no header", func(t *testing.T) {
		fake := &httpFakeCaller{httpResults: []hostHTTPResponse{{
			StatusCode: 503,
			Body:       mustJSON(t, map[string]any{"token": ""}),
		}}}
		m := newAuthTestManager(t, fake)
		acq := m.acquireAuthSentinel("cb-1", matrixDeviceID, newSentinelGenerator(matrixDeviceID, "UA-FIXED", "sid-x"))
		if acq.err != nil || acq.token != "" || acq.oaiSC != "" {
			t.Fatalf("refused-challenge acquisition = %+v, want empty", acq)
		}
	})

	t.Run("required:false answers a requirements token", func(t *testing.T) {
		fake := &httpFakeCaller{httpResults: []hostHTTPResponse{{
			StatusCode: 200,
			Body: mustJSON(t, map[string]any{
				"token":       testChallengeToken,
				"proofofwork": map[string]any{"required": false},
			}),
		}}}
		m := newAuthTestManager(t, fake)
		acq := m.acquireAuthSentinel("cb-1", matrixDeviceID, newSentinelGenerator(matrixDeviceID, "UA-FIXED", "sid-x"))
		if acq.err != nil || acq.oaiSC != "0"+testChallengeToken {
			t.Fatalf("acquisition = %+v, want oai-sc 0+challenge", acq)
		}
		var value sentinelValue
		_ = json.Unmarshal([]byte(acq.token), &value)
		if !strings.HasPrefix(value.P, "gAAAAAC") || value.C != testChallengeToken {
			t.Errorf("value = %+v, want requirements p + server challenge c", value)
		}
	})
}

// passwordLoginRequestBody builds the auth.login.password wire request.
func passwordLoginRequestBody(t *testing.T, email, password, callbackID string) []byte {
	t.Helper()
	body, err := json.Marshal(passwordLoginRequest{
		Provider:       providerKey,
		Email:          email,
		Password:       password,
		HostCallbackID: callbackID,
	})
	if err != nil {
		t.Fatalf("marshal auth.login.password request: %v", err)
	}
	return body
}

// passwordLoginAuthorizeScript returns the two scripted responses every happy
// path starts with: the authorize bootstrap (200) and the sentinel challenge
// (200, no PoW required).
func passwordLoginAuthorizeScript(t *testing.T) []hostHTTPResponse {
	t.Helper()
	return []hostHTTPResponse{
		{StatusCode: 200, Body: []byte("<html>login page</html>")},
		{StatusCode: 200, Body: mustJSON(t, map[string]any{
			"token":       testChallengeToken,
			"proofofwork": map[string]any{"required": false},
		})},
	}
}

// decodePasswordLoginRequests walks the fake caller's recorded host.http.do
// calls and decodes each one.
func decodePasswordLoginRequests(t *testing.T, fake *httpFakeCaller) []hostHTTPRequest {
	t.Helper()
	fake.mu.Lock()
	defer fake.mu.Unlock()
	out := make([]hostHTTPRequest, 0, len(fake.calls))
	for _, record := range fake.calls {
		var req hostHTTPRequest
		if err := json.Unmarshal(record.request, &req); err != nil {
			t.Fatalf("decode captured host.http.do request: %v", err)
		}
		out = append(out, req)
	}
	return out
}

// TestPasswordLoginRequestShapes pins every outbound request of the happy
// path byte-for-byte against the reference flow (account_service.py:585-834):
// the authorize bootstrap (16 params, reference order, login_hint email), the
// sentinel req (flow password_verify), the verify (JSON password body,
// oai-did/oai-sc cookies, openai-sentinel-token), the token exchange (five
// grant fields, auth0-client header) and the /backend-api/me verify.
func TestPasswordLoginRequestShapes(t *testing.T) {
	script := passwordLoginAuthorizeScript(t)
	script = append(script,
		hostHTTPResponse{StatusCode: 200, Body: mustJSON(t, map[string]any{
			"continue_url": "https://platform.openai.com/auth/callback?code=PASS-CODE-123&state=st-1&other=1",
		})},
		hostHTTPResponse{StatusCode: 200, Body: mustJSON(t, map[string]any{
			"access_token":  "pw-access-token",
			"refresh_token": "pw-refresh-token",
			"id_token":      "pw-id-token",
		})},
		hostHTTPResponse{StatusCode: 200, Body: mustJSON(t, map[string]any{
			"id":    "account-9",
			"email": testPasswordEmail,
		})},
		hostHTTPResponse{StatusCode: 200, Body: mustJSON(t, map[string]any{
			"accounts": map[string]any{"default": map[string]any{"account": map[string]any{"plan_type": "plus"}}},
		})},
	)
	fake := &httpFakeCaller{httpResults: script}
	m := newAuthTestManager(t, fake)

	resp, err := m.Handle(methodAuthLoginPassword, passwordLoginRequestBody(t, testPasswordEmail, testPasswordSecret, "cb-pw"))
	if err != nil {
		t.Fatalf("Handle(auth.login.password): %v", err)
	}
	out := decodeLoginPoll(t, resp)
	if out.Status != pluginapi.AuthLoginStatusSuccess {
		t.Fatalf("Status = %q, want success: %s", out.Status, resp)
	}

	reqs := decodePasswordLoginRequests(t, fake)
	if len(reqs) != 6 {
		t.Fatalf("flow made %d transport calls, want 6 (authorize, sentinel, verify, exchange, me, plan probe): %v", len(reqs), fake.methods())
	}
	// The plan probe (call 5) runs through the upstream package's own
	// transport seam, which carries no callback scope — like the browser
	// login. The flow's own five requests are all scoped to cb-pw.
	for i, req := range reqs[:5] {
		if req.HostCallbackID != "cb-pw" {
			t.Errorf("call %d host_callback_id = %q, want cb-pw", i, req.HostCallbackID)
		}
	}

	// ① authorize bootstrap.
	auth := reqs[0]
	if auth.Method != "GET" {
		t.Fatalf("authorize method = %q, want GET", auth.Method)
	}
	if !strings.HasPrefix(auth.URL, oauthAuthorizeBase+oauthAuthorizePath+"?") {
		t.Fatalf("authorize URL = %q, want the pinned origin + path", auth.URL)
	}
	q, err := url.ParseQuery(strings.TrimPrefix(auth.URL, oauthAuthorizeBase+oauthAuthorizePath+"?"))
	if err != nil {
		t.Fatalf("authorize query does not parse: %v", err)
	}
	if len(q) != 16 {
		t.Fatalf("authorize has %d params, want exactly 16: %v", len(q), q)
	}
	wantParams := map[string]string{
		"issuer":                oauthAuthorizeBase,
		"client_id":             oauthClientID,
		"audience":              oauthLoginAudience,
		"redirect_uri":          oauthLoginRedirectURI,
		"screen_hint":           "login_or_signup",
		"max_age":               "0",
		"login_hint":            testPasswordEmail,
		"scope":                 oauthLoginScope,
		"response_type":         "code",
		"response_mode":         "query",
		"code_challenge_method": "S256",
		"auth0Client":           passwordAuth0Client,
	}
	for key, want := range wantParams {
		if got := q.Get(key); got != want {
			t.Errorf("authorize param %s = %q, want %q", key, got, want)
		}
	}
	deviceID := q.Get("device_id")
	if deviceID == "" || q.Get("state") == "" || q.Get("nonce") == "" || q.Get("code_challenge") == "" {
		t.Fatalf("authorize URL misses the per-flow identifiers: %v", q)
	}
	// state/nonce: 32 chars, secrets.token_urlsafe(32) shape (base64url-24).
	for _, name := range []string{"state", "nonce"} {
		if got := len(q.Get(name)); got != 32 {
			t.Errorf("authorize %s length = %d, want 32 (token_urlsafe(32))", name, got)
		}
	}
	if ref := strings.Join(auth.Headers["Referer"], ","); ref != "https://platform.openai.com/" {
		t.Errorf("authorize Referer = %q", ref)
	}
	if sf := strings.Join(auth.Headers["sec-fetch-site"], ","); sf != "cross-site" {
		t.Errorf("authorize sec-fetch-site = %q", sf)
	}
	if cookie := strings.Join(auth.Headers["Cookie"], ","); cookie != "oai-did="+deviceID {
		t.Errorf("authorize Cookie = %q, want oai-did=<device_id>", cookie)
	}

	// ② sentinel req.
	sent := reqs[1]
	if sent.URL != sentinelReqURL || sent.Method != "POST" {
		t.Fatalf("sentinel call = %s %s", sent.Method, sent.URL)
	}
	var sentBody struct {
		P    string `json:"p"`
		ID   string `json:"id"`
		Flow string `json:"flow"`
	}
	if err := json.Unmarshal(sent.Body, &sentBody); err != nil {
		t.Fatalf("sentinel body is not JSON: %v", err)
	}
	if !strings.HasPrefix(sentBody.P, "gAAAAAC") || sentBody.ID != deviceID || sentBody.Flow != sentinelFlowPasswordVerify {
		t.Errorf("sentinel body = %+v, want requirements p + device id + flow password_verify", sentBody)
	}

	// ③ password verify: JSON body carrying ONLY the password, the sentinel
	// header decoded to its five fields, the oai-did + oai-sc cookies.
	verify := reqs[2]
	if verify.Method != "POST" || verify.URL != passwordVerifyURL {
		t.Fatalf("verify call = %s %s", verify.Method, verify.URL)
	}
	if got := string(verify.Body); got != `{"password":"`+testPasswordSecret+`"}` {
		t.Errorf("verify body = %q, want the single-field JSON password body", got)
	}
	sentinelHeader := strings.Join(verify.Headers["openai-sentinel-token"], ",")
	var sentVal sentinelValue
	if err := json.Unmarshal([]byte(sentinelHeader), &sentVal); err != nil {
		t.Fatalf("openai-sentinel-token is not JSON: %v", err)
	}
	if !strings.HasPrefix(sentVal.P, "gAAAAAC") || sentVal.T != "" || sentVal.C != testChallengeToken || sentVal.ID != deviceID || sentVal.Flow != sentinelFlowPasswordVerify {
		t.Errorf("sentinel value = %+v", sentVal)
	}
	if cookie := strings.Join(verify.Headers["Cookie"], ","); cookie != "oai-did="+deviceID+"; oai-sc=0"+testChallengeToken {
		t.Errorf("verify Cookie = %q, want oai-did + oai-sc (0+challenge)", cookie)
	}
	if did := strings.Join(verify.Headers["oai-device-id"], ","); did != deviceID {
		t.Errorf("verify oai-device-id = %q, want the device id", did)
	}
	if ct := strings.Join(verify.Headers["Content-Type"], ","); ct != "application/json" {
		t.Errorf("verify Content-Type = %q", ct)
	}
	if ref := strings.Join(verify.Headers["Referer"], ","); ref != oauthAuthorizeBase+"/email-verification" {
		t.Errorf("verify Referer = %q", ref)
	}
	if sf := strings.Join(verify.Headers["sec-fetch-site"], ","); sf != "same-origin" {
		t.Errorf("verify sec-fetch-site = %q", sf)
	}

	// ④ token exchange: exactly the five grant fields with the flow's own
	// PKCE verifier and the pinned registered redirect_uri.
	exchange := reqs[3]
	if exchange.Method != "POST" || exchange.URL != oauthLoginTokenURL {
		t.Fatalf("exchange call = %s %s", exchange.Method, exchange.URL)
	}
	var exchangeBody passwordTokenExchangeBody
	if err := json.Unmarshal(exchange.Body, &exchangeBody); err != nil {
		t.Fatalf("exchange body is not JSON: %v", err)
	}
	if exchangeBody.ClientID != oauthClientID || exchangeBody.GrantType != "authorization_code" ||
		exchangeBody.Code != "PASS-CODE-123" || exchangeBody.RedirectURI != oauthLoginRedirectURI {
		t.Errorf("exchange body = %+v", exchangeBody)
	}
	// PKCE: the challenge sent at authorize is S256 of the verifier sent at
	// exchange; the verifier is 86 base64url chars (64 random bytes — the
	// reference utils/pkce.py shape).
	// 64 random bytes → base64url without padding: ceil(64/3)*4 = 86 chars
	// (21 three-byte groups + one two-byte group). The reference pkce.py
	// emits exactly this length (verified: 86).
	if got := len(exchangeBody.CodeVerifier); got != 86 {
		t.Errorf("verifier length = %d, want 86 (%d random bytes base64url)", got, passwordPKCEBytes)
	}
	digest := sha256.Sum256([]byte(exchangeBody.CodeVerifier))
	if want := base64.RawURLEncoding.EncodeToString(digest[:]); q.Get("code_challenge") != want {
		t.Errorf("authorize challenge != S256(exchange verifier)")
	}
	if ach := strings.Join(exchange.Headers["auth0-client"], ","); ach != passwordAuth0Client {
		t.Errorf("exchange auth0-client = %q, want the auth0-spa-js challenge JSON", ach)
	}
	if sf := strings.Join(exchange.Headers["sec-fetch-site"], ","); sf != "same-site" {
		t.Errorf("exchange sec-fetch-site = %q", sf)
	}
	if cookie := strings.Join(exchange.Headers["Cookie"], ","); cookie != "oai-did="+deviceID+"; oai-sc=0"+testChallengeToken {
		t.Errorf("exchange Cookie = %q", cookie)
	}

	// ⑤ /backend-api/me + ⑥ plan probe with the fresh bearer.
	for i, req := range []hostHTTPRequest{reqs[4], reqs[5]} {
		if authz := strings.Join(req.Headers["Authorization"], ","); authz != "Bearer pw-access-token" {
			t.Errorf("call %d Authorization = %q, want the fresh bearer", i+4, authz)
		}
	}
	if reqs[4].URL != chatgptMeURL {
		t.Errorf("me call URL = %q", reqs[4].URL)
	}
}

// TestPasswordLoginContinueURLParsing pins the continue_url handling: the
// code is extracted from the query string; a missing code answers no_auth_code
// (or need_verification_code for an email-OTP page) with NO token exchange
// attempted; a state/other query params never leak into the exchange.
func TestPasswordLoginContinueURLParsing(t *testing.T) {
	t.Run("code extracted from continue_url", func(t *testing.T) {
		if got := extractContinueURLCode("https://platform.openai.com/auth/callback?code=EXTRACTED-CODE&state=whatever&foo=bar"); got != "EXTRACTED-CODE" {
			t.Fatalf("extractContinueURLCode = %q, want EXTRACTED-CODE", got)
		}
		if got := extractContinueURLCode("  "); got != "" {
			t.Fatalf("blank continue_url = %q, want empty", got)
		}
		if got := extractContinueURLCode("https://platform.openai.com/auth/callback?state=x"); got != "" {
			t.Fatalf("continue_url without code = %q, want empty", got)
		}
	})

	t.Run("missing code without page type is no_auth_code", func(t *testing.T) {
		fake := &httpFakeCaller{httpResults: append(passwordLoginAuthorizeScript(t),
			hostHTTPResponse{StatusCode: 200, Body: mustJSON(t, map[string]any{"continue_url": ""})},
		)}
		m := newAuthTestManager(t, fake)
		resp, err := m.Handle(methodAuthLoginPassword, passwordLoginRequestBody(t, testPasswordEmail, testPasswordSecret, "cb-1"))
		if err != nil {
			t.Fatalf("Handle: %v", err)
		}
		env := decodeErrorEnvelope(t, resp)
		if env.Error.Code != errNoAuthCode || env.Error.HTTPStatus != 502 || !env.Error.Retryable {
			t.Fatalf("error = %+v, want retryable no_auth_code 502", env.Error)
		}
		if got := len(decodePasswordLoginRequests(t, fake)); got != 3 {
			t.Fatalf("no-code path made %d transport calls, want 3 (no exchange, no verify)", got)
		}
	})

	t.Run("email OTP page is headless-unusable", func(t *testing.T) {
		fake := &httpFakeCaller{httpResults: append(passwordLoginAuthorizeScript(t),
			hostHTTPResponse{StatusCode: 200, Body: mustJSON(t, map[string]any{
				"page": map[string]any{"type": "email_otp_verification"},
			})},
		)}
		m := newAuthTestManager(t, fake)
		resp, err := m.Handle(methodAuthLoginPassword, passwordLoginRequestBody(t, testPasswordEmail, testPasswordSecret, "cb-1"))
		if err != nil {
			t.Fatalf("Handle: %v", err)
		}
		env := decodeErrorEnvelope(t, resp)
		if env.Error.Code != errNeedVerificationCode || env.Error.HTTPStatus != 403 || env.Error.Retryable {
			t.Fatalf("error = %+v, want non-retryable need_verification_code 403", env.Error)
		}
		if got := len(decodePasswordLoginRequests(t, fake)); got != 3 {
			t.Fatalf("OTP path made %d transport calls, want 3 — the code was never exchanged", got)
		}
	})
}

// TestPasswordLoginVerifyFailures pins the verify refusal classification
// (account_service.py:716-725) AND the leak rule: every refusal answers a
// FIXED typed message — the upstream body (canary marker) must never appear
// in the envelope, because an error body could echo credential material.
func TestPasswordLoginVerifyFailures(t *testing.T) {
	cases := []struct {
		name      string
		status    int
		body      string
		wantCode  string
		wantHTTP  int
		wantRetry bool
	}{
		{
			name: "invalid credentials", status: 401,
			body:     `{"error":{"code":"a200","message":"Invalid credentials"}}`,
			wantCode: errInvalidPassword, wantHTTP: 401,
		},
		{
			name: "wrong password marker", status: 401,
			body:     `{"error":{"code":"a201","message":"the Wrong Password you gave is not right"}}`,
			wantCode: errInvalidPassword, wantHTTP: 401,
		},
		{
			name: "unsupported region", status: 403,
			body:     `{"error":{"code":"unsupported_country_region_territory","message":"region"}}`,
			wantCode: errUnsupportedRegion, wantHTTP: 403,
		},
		{
			name: "invalid state", status: 400,
			body:     `{"error":{"code":"invalid_state","message":"stale"}}`,
			wantCode: errLoginStateInvalid, wantHTTP: 400, wantRetry: true,
		},
		{
			name: "generic refusal", status: 400,
			body:     `{"error":{"code":"CANARY-ERROR-CODE","message":"CANARY-ECHO-MARKER"}}`,
			wantCode: errPasswordVerifyFailed, wantHTTP: 502, wantRetry: true,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			fake := &httpFakeCaller{httpResults: append(passwordLoginAuthorizeScript(t),
				hostHTTPResponse{StatusCode: tc.status, Body: []byte(tc.body)},
			)}
			m := newAuthTestManager(t, fake)
			resp, err := m.Handle(methodAuthLoginPassword, passwordLoginRequestBody(t, testPasswordEmail, testPasswordSecret, "cb-1"))
			if err != nil {
				t.Fatalf("Handle: %v", err)
			}
			env := decodeErrorEnvelope(t, resp)
			if env.Error.Code != tc.wantCode || env.Error.HTTPStatus != tc.wantHTTP || env.Error.Retryable != tc.wantRetry {
				t.Fatalf("error = %+v, want %s/%d retry=%v", env.Error, tc.wantCode, tc.wantHTTP, tc.wantRetry)
			}
			// The upstream body must not round-trip: fixed messages only.
			for _, canary := range []string{"CANARY-ECHO-MARKER", "CANARY-ERROR-CODE"} {
				if strings.Contains(string(resp), canary) {
					t.Fatalf("verify failure envelope echoed the upstream body: %s", resp)
				}
			}
			if strings.Contains(string(resp), testPasswordSecret) {
				t.Fatalf("verify failure envelope leaked the password: %s", resp)
			}
			if got := len(decodePasswordLoginRequests(t, fake)); got != 3 {
				t.Fatalf("verify failure made %d transport calls, want 3", got)
			}
		})
	}
}

// TestPasswordLoginAuthorizeErrorRedirect pins the authorize bootstrap's
// error-page handling (account_service.py:658-673): a 302 whose Location
// carries the base64 payload is decoded; rate_limit_exceeded is its own typed
// class, any other errorCode is login_failed, and the loop stops there.
func TestPasswordLoginAuthorizeErrorRedirect(t *testing.T) {
	payload := base64.StdEncoding.EncodeToString([]byte(`{"errorCode":"rate_limit_exceeded"}`))
	fake := &httpFakeCaller{httpResults: []hostHTTPResponse{{
		StatusCode: 302,
		Headers:    map[string][]string{"Location": {oauthAuthorizeBase + "/error?payload=" + payload}},
	}}}
	m := newAuthTestManager(t, fake)
	resp, err := m.Handle(methodAuthLoginPassword, passwordLoginRequestBody(t, testPasswordEmail, testPasswordSecret, "cb-1"))
	if err != nil {
		t.Fatalf("Handle: %v", err)
	}
	env := decodeErrorEnvelope(t, resp)
	if env.Error.Code != errLoginRateLimited || env.Error.HTTPStatus != 429 || !env.Error.Retryable {
		t.Fatalf("error = %+v, want retryable rate_limit_exceeded 429", env.Error)
	}
	if got := len(decodePasswordLoginRequests(t, fake)); got != 1 {
		t.Fatalf("rate-limited authorize made %d transport calls, want 1", got)
	}

	// A foreign errorCode answers login_failed with the short code token,
	// never the payload body.
	other := base64.StdEncoding.EncodeToString([]byte(`{"errorCode":"CANARY-ERROR-PAGE","detail":"secret-stuff"}`))
	fake = &httpFakeCaller{httpResults: []hostHTTPResponse{{
		StatusCode: 302,
		Headers:    map[string][]string{"Location": {oauthAuthorizeBase + "/error?payload=" + other}},
	}}}
	m = newAuthTestManager(t, fake)
	resp, err = m.Handle(methodAuthLoginPassword, passwordLoginRequestBody(t, testPasswordEmail, testPasswordSecret, "cb-1"))
	if err != nil {
		t.Fatalf("Handle: %v", err)
	}
	env = decodeErrorEnvelope(t, resp)
	if env.Error.Code != "login_failed" {
		t.Fatalf("error code = %q, want login_failed", env.Error.Code)
	}
	if !strings.Contains(env.Error.Message, "CANARY-ERROR-PAGE") {
		t.Errorf("error should carry the short provider errorCode: %q", env.Error.Message)
	}
	if strings.Contains(env.Error.Message, "secret-stuff") {
		t.Errorf("error echoed the payload body: %q", env.Error.Message)
	}
}

// TestPasswordLoginSuccessStoresCredential pins the storage contract: the
// recovered triple lands in the EXACT auth-file shape the browser login
// produces — source_type "password", stable hashed file name, the plan
// persisted from the probe — and the record passes auth.parse unchanged, so
// the refresh-retry and quota machinery work on it.
func TestPasswordLoginSuccessStoresCredential(t *testing.T) {
	script := passwordLoginAuthorizeScript(t)
	script = append(script,
		hostHTTPResponse{StatusCode: 200, Body: mustJSON(t, map[string]any{
			"continue_url": "https://platform.openai.com/auth/callback?code=PASS-CODE-123&state=st",
		})},
		hostHTTPResponse{StatusCode: 200, Body: mustJSON(t, map[string]any{
			"access_token":  "pw-access-token",
			"refresh_token": "pw-refresh-token",
			"id_token":      "pw-id-token",
		})},
		hostHTTPResponse{StatusCode: 200, Body: mustJSON(t, map[string]any{
			"id":    "account-9",
			"email": testPasswordEmail,
		})},
		hostHTTPResponse{StatusCode: 200, Body: mustJSON(t, map[string]any{
			"accounts": map[string]any{"default": map[string]any{"account": map[string]any{"plan_type": "plus"}}},
		})},
	)
	fake := &httpFakeCaller{httpResults: script}
	m := newAuthTestManager(t, fake)

	resp, err := m.Handle(methodAuthLoginPassword, passwordLoginRequestBody(t, testPasswordEmail, testPasswordSecret, "cb-1"))
	if err != nil {
		t.Fatalf("Handle: %v", err)
	}
	out := decodeLoginPoll(t, resp)
	if out.Status != pluginapi.AuthLoginStatusSuccess {
		t.Fatalf("Status = %q, want success: %s", out.Status, resp)
	}
	if out.Auth.Provider != providerKey || out.Auth.FileName != out.Auth.ID {
		t.Fatalf("Auth = %+v, want the provider record", out.Auth)
	}
	cred, err := FromStorageJSON(out.Auth.StorageJSON)
	if err != nil {
		t.Fatalf("FromStorageJSON: %v", err)
	}
	if cred.AccessToken != "pw-access-token" || cred.RefreshToken != "pw-refresh-token" || cred.IDToken != "pw-id-token" {
		t.Errorf("token triple not applied: %+v", cred)
	}
	if cred.Email != testPasswordEmail || cred.AccountID != "account-9" {
		t.Errorf("identity facts not applied: %+v", cred)
	}
	if cred.SourceType != passwordSourceLogin {
		t.Errorf("SourceType = %q, want %q", cred.SourceType, passwordSourceLogin)
	}
	if cred.Plan != "plus" {
		t.Errorf("persisted Plan = %q, want plus from the probe", cred.Plan)
	}
	if want := FileNameFor(cred); out.Auth.FileName != want {
		t.Errorf("Auth.FileName = %q, want %q (stable hash, never an email)", out.Auth.FileName, want)
	}
	if strings.Contains(out.Auth.FileName, "example.com") {
		t.Errorf("file name carries the email: %q", out.Auth.FileName)
	}
	if typ, _ := out.Auth.Metadata["type"].(string); typ != providerKey {
		t.Errorf("Auth.Metadata[type] = %v, want %q", out.Auth.Metadata["type"], providerKey)
	}

	// The recovered record passes auth.parse exactly like a browser-login
	// record does (fail-closed type check + normalization round-trip).
	parseResp, err := m.Handle(pluginabi.MethodAuthParse, authParseRequestBody(t, providerKey, out.Auth.FileName, out.Auth.StorageJSON))
	if err != nil {
		t.Fatalf("Handle(auth.parse): %v", err)
	}
	var parsed pluginapi.AuthParseResponse
	if err := json.Unmarshal(decodeEnv(t, parseResp).Result, &parsed); err != nil {
		t.Fatalf("decode auth.parse result: %v", err)
	}
	if !parsed.Handled {
		t.Fatalf("auth.parse refused the recovered record")
	}
	reparsed, err := FromStorageJSON(parsed.Auth.StorageJSON)
	if err != nil {
		t.Fatalf("FromStorageJSON(round-trip): %v", err)
	}
	if reparsed.AccessToken != cred.AccessToken || reparsed.RefreshToken != cred.RefreshToken ||
		reparsed.IDToken != cred.IDToken || reparsed.SourceType != cred.SourceType {
		t.Errorf("auth.parse round-trip altered the record: %+v vs %+v", reparsed, cred)
	}
}

// TestPasswordLoginSecretHygiene pins the secret rule: the password crosses
// the ABI ONLY as this RPC's input and appears ONLY in the verify request
// body. Every other outbound byte (authorize URL, sentinel body/headers,
// exchange, me, plan probe) and every response envelope (success and every
// typed refusal) is scanned for it.
func TestPasswordLoginSecretHygiene(t *testing.T) {
	type scenario struct {
		name   string
		script []hostHTTPResponse
	}
	otp := hostHTTPResponse{StatusCode: 200, Body: mustJSON(t, map[string]any{
		"page": map[string]any{"type": "email_otp_verification"},
	})}
	badPw := hostHTTPResponse{StatusCode: 401, Body: []byte(`{"error":{"code":"a200","message":"Invalid credentials"}}`)}
	successTail := []hostHTTPResponse{
		{StatusCode: 200, Body: mustJSON(t, map[string]any{"continue_url": "https://platform.openai.com/auth/callback?code=C&state=s"})},
		{StatusCode: 200, Body: mustJSON(t, map[string]any{"access_token": "a", "refresh_token": "r", "id_token": "i"})},
		{StatusCode: 200, Body: mustJSON(t, map[string]any{"id": "acc", "email": testPasswordEmail})},
		{StatusCode: 200, Body: mustJSON(t, map[string]any{"accounts": map[string]any{"default": map[string]any{"account": map[string]any{"plan_type": "free"}}}})},
	}
	scenarios := []scenario{
		{"success", append(append([]hostHTTPResponse{}, passwordLoginAuthorizeScript(t)...), successTail...)},
		{"otp refusal", append(passwordLoginAuthorizeScript(t), otp)},
		{"invalid password", append(passwordLoginAuthorizeScript(t), badPw)},
	}
	for _, tc := range scenarios {
		t.Run(tc.name, func(t *testing.T) {
			fake := &httpFakeCaller{httpResults: tc.script}
			m := newAuthTestManager(t, fake)
			resp, err := m.Handle(methodAuthLoginPassword, passwordLoginRequestBody(t, testPasswordEmail, testPasswordSecret, "cb-1"))
			if err != nil {
				t.Fatalf("Handle: %v", err)
			}

			reqs := decodePasswordLoginRequests(t, fake)
			verifySeen := false
			for i, req := range reqs {
				onWire := req.URL + "\x00" + string(req.Body)
				for name, values := range req.Headers {
					onWire += "\x00" + name + ":" + strings.Join(values, ",")
				}
				if req.URL == passwordVerifyURL {
					if !strings.Contains(string(req.Body), testPasswordSecret) {
						t.Fatalf("call %d: the verify body never carried the password", i)
					}
					verifySeen = true
					continue // the ONLY place the password is allowed to travel
				}
				if strings.Contains(onWire, testPasswordSecret) {
					t.Fatalf("call %d (%s) carried the password outside the verify body", i, req.URL)
				}
			}
			if !verifySeen {
				t.Fatalf("the flow never issued the verify request: %v", fake.methods())
			}
			if strings.Contains(string(resp), testPasswordSecret) {
				t.Fatalf("response envelope leaked the password: %s", resp)
			}
		})
	}
}

// TestPasswordPKCE pins the password-flow PKCE pair against the reference
// derivation (utils/pkce.py): base64url(sha256(ascii(verifier))) and the
// 64-random-byte verifier (86 base64url chars). The fixed-vector row is the
// RFC 7636 appendix B pair, cross-checked by running the reference pkce
// derivation once (Python 3.13.7, 2026-11-09).
func TestPasswordPKCE(t *testing.T) {
	verifier, challenge, err := pkcePairBytes(passwordPKCEBytes)
	if err != nil {
		t.Fatalf("pkcePairBytes: %v", err)
	}
	if len(verifier) != 86 {
		t.Fatalf("verifier length = %d, want 86 (64 random bytes base64url, reference utils/pkce.py)", len(verifier))
	}
	const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"
	for _, r := range verifier + challenge {
		if !strings.ContainsRune(alphabet, r) {
			t.Fatalf("PKCE pair has out-of-charset rune %q", r)
		}
	}
	digest := sha256.Sum256([]byte(verifier))
	if want := base64.RawURLEncoding.EncodeToString(digest[:]); challenge != want {
		t.Fatalf("challenge = %q, want S256(verifier) %q", challenge, want)
	}
	// RFC 7636 appendix B vector, through the reference's own derivation.
	const rfcVerifier = "dBjftJeZ4CVP-mB92K27uhbUJU1p1r_wW1gFWFOEjXk"
	digest = sha256.Sum256([]byte(rfcVerifier))
	if got := base64.RawURLEncoding.EncodeToString(digest[:]); got != "E9Melhoa2OwvFrEMTJguCHaoeK1t8URWbuGJSstw-cM" {
		t.Fatalf("RFC 7636 appendix B derivation = %q", got)
	}
}

// TestPasswordLoginInvalidRequest pins fail-closed input validation: missing
// email, missing password and malformed JSON answer invalid_request 400
// without touching the transport seam.
func TestPasswordLoginInvalidRequest(t *testing.T) {
	cases := []struct {
		name string
		body []byte
	}{
		{"malformed json", []byte("{")},
		{"missing email", []byte(`{"Password":"p"}`)},
		{"blank email", []byte(`{"Email":"   ","Password":"p"}`)},
		{"missing password", []byte(`{"Email":"a@example.com"}`)},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			fake := &httpFakeCaller{}
			m := newAuthTestManager(t, fake)
			resp, err := m.Handle(methodAuthLoginPassword, tc.body)
			if err != nil {
				t.Fatalf("Handle: %v", err)
			}
			env := decodeErrorEnvelope(t, resp)
			if env.Error.Code != "invalid_request" || env.Error.HTTPStatus != 400 {
				t.Fatalf("error = %+v, want invalid_request 400", env.Error)
			}
			if len(fake.calls) != 0 {
				t.Fatalf("invalid request touched the transport: %v", fake.methods())
			}
		})
	}
}
